<?php
declare(strict_types=1);

require_once dirname(__DIR__) . '/config.php';
exigirAdmin();

$erro='';$sucesso='';$treinamentoSelecionado=max(0,(int)($_GET['treinamento_id']??$_POST['treinamento_id']??0));$editarId=max(0,(int)($_GET['editar']??$_POST['aula_id']??0));
if($_SERVER['REQUEST_METHOD']==='POST'){
    $acao=(string)($_POST['acao']??'salvar');
    if(!validarCsrf($_POST['csrf_token']??null)){$erro='A solicitação expirou. Atualize a página.';}
    else{try{
        if($acao==='excluir'){$stmt=$pdo->prepare('SELECT titulo FROM aulas WHERE id=?');$stmt->execute([$editarId]);$titulo=$stmt->fetchColumn();if($titulo===false){$erro='Aula não encontrada.';}else{$stmt=$pdo->prepare('DELETE FROM aulas WHERE id=?');$stmt->execute([$editarId]);registrarAtividade($pdo,(int)$_SESSION['usuario_id'],'removeu a aula',(string)$titulo);$sucesso='Aula removida.';$editarId=0;}}
        else{$treinamentoSelecionado=(int)($_POST['treinamento_id']??0);$titulo=trim((string)($_POST['titulo']??''));$objetivo=trim((string)($_POST['objetivo']??''));$conteudo=trim((string)($_POST['conteudo']??''));$duracao=max(0,(int)($_POST['duracao_min']??0));$ordem=max(1,(int)($_POST['ordem']??1));$status=(string)($_POST['status']??'publicado');if($treinamentoSelecionado<1||mb_strlen($titulo)<3||$conteudo===''||!in_array($status,['rascunho','publicado'],true)){$erro='Informe treinamento, título, conteúdo e status válidos.';}elseif($editarId){$stmt=$pdo->prepare('UPDATE aulas SET treinamento_id=?,titulo=?,objetivo=?,conteudo=?,duracao_min=?,ordem=?,status=?,atualizado_em=CURRENT_TIMESTAMP WHERE id=?');$stmt->execute([$treinamentoSelecionado,$titulo,$objetivo,$conteudo,$duracao,$ordem,$status,$editarId]);registrarAtividade($pdo,(int)$_SESSION['usuario_id'],'editou a aula',$titulo);$sucesso='Aula atualizada.';}else{$stmt=$pdo->prepare('INSERT INTO aulas (treinamento_id,titulo,objetivo,conteudo,duracao_min,ordem,status) VALUES (?,?,?,?,?,?,?)');$stmt->execute([$treinamentoSelecionado,$titulo,$objetivo,$conteudo,$duracao,$ordem,$status]);registrarAtividade($pdo,(int)$_SESSION['usuario_id'],'criou a aula',$titulo);$sucesso='Aula cadastrada.';}}
    }catch(Throwable $e){registrarErro($pdo,'gerenciamento de aulas',$e);$erro='Não foi possível concluir a operação.';}}
}
$treinamentos=$pdo->query('SELECT id,titulo FROM treinamentos ORDER BY titulo')->fetchAll();$sql='SELECT a.*,t.titulo AS treinamento_titulo,(SELECT COUNT(*) FROM materiais m WHERE m.aula_id=a.id) AS total_materiais FROM aulas a JOIN treinamentos t ON t.id=a.treinamento_id';$params=[];if($treinamentoSelecionado){$sql.=' WHERE a.treinamento_id=?';$params[]=$treinamentoSelecionado;}$sql.=' ORDER BY t.titulo,a.ordem,a.id';$stmt=$pdo->prepare($sql);$stmt->execute($params);$aulas=$stmt->fetchAll();$edicao=['treinamento_id'=>$treinamentoSelecionado,'titulo'=>'','objetivo'=>'','conteudo'=>'','duracao_min'=>30,'ordem'=>1,'status'=>'publicado'];if($editarId){$stmt=$pdo->prepare('SELECT * FROM aulas WHERE id=?');$stmt->execute([$editarId]);$edicao=$stmt->fetch()?:$edicao;$treinamentoSelecionado=(int)$edicao['treinamento_id'];}
?><!DOCTYPE html><html lang="pt-BR"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>TrainHub - Aulas</title><link rel="stylesheet" href="css/app.css?v=1.0"></head><body><header class="th-topbar"><a class="th-logo" href="dashboard.php"><img src="assets/logo.png" alt="TrainHub"></a><a class="th-avatar" href="perfil.php">●</a></header><main class="th-shell"><a class="th-back" href="dashboard.php">←</a><div class="th-heading"><div><h1>Aulas</h1><p>Organize o conteúdo e a sequência dos treinamentos.</p></div></div><?php if($erro):?><p class="th-alert th-alert-error"><?php echo esc($erro);?></p><?php endif;?><?php if($sucesso):?><p class="th-alert th-alert-success"><?php echo esc($sucesso);?></p><?php endif;?><div class="th-grid"><section class="th-panel"><form class="th-toolbar" method="get"><select class="th-input" name="treinamento_id" onchange="this.form.submit()"><option value="0">Todos os treinamentos</option><?php foreach($treinamentos as $treinamento):?><option value="<?php echo (int)$treinamento['id'];?>" <?php echo $treinamentoSelecionado===(int)$treinamento['id']?'selected':'';?>><?php echo esc($treinamento['titulo']);?></option><?php endforeach;?></select></form><div class="th-list"><?php if(!$aulas):?><p class="th-empty">Nenhuma aula cadastrada para este filtro.</p><?php endif;?><?php foreach($aulas as $aula):?><article class="th-card"><div class="th-card-row"><div><span class="th-meta"><?php echo esc($aula['treinamento_titulo']);?></span><h3><?php echo (int)$aula['ordem'];?>. <?php echo esc($aula['titulo']);?></h3></div><span class="th-badge <?php echo $aula['status']==='publicado'?'th-badge-success':'th-badge-warning';?>"><?php echo esc($aula['status']);?></span></div><p><?php echo esc($aula['objetivo']?:'Sem objetivo informado.');?></p><div class="th-card-row"><span class="th-meta"><?php echo (int)$aula['duracao_min'];?> min · <?php echo (int)$aula['total_materiais'];?> materiais</span><div class="th-actions"><a class="th-button th-button-secondary" href="aula-template.php?id=<?php echo (int)$aula['id'];?>">Visualizar</a><a class="th-button" href="aulas.php?editar=<?php echo (int)$aula['id'];?>">Editar</a></div></div></article><?php endforeach;?></div></section><aside class="th-panel"><h2><?php echo $editarId?'Editar aula':'Nova aula';?></h2><form class="th-form" method="post"><?php echo csrfInput();?><input type="hidden" name="acao" value="salvar"><input type="hidden" name="aula_id" value="<?php echo $editarId;?>"><label class="th-field">Treinamento<select name="treinamento_id" required><option value="">Selecione</option><?php foreach($treinamentos as $treinamento):?><option value="<?php echo (int)$treinamento['id'];?>" <?php echo (int)$edicao['treinamento_id']===(int)$treinamento['id']?'selected':'';?>><?php echo esc($treinamento['titulo']);?></option><?php endforeach;?></select></label><div class="th-form-row"><label class="th-field">Título<input name="titulo" maxlength="200" value="<?php echo esc($edicao['titulo']);?>" required></label><label class="th-field">Ordem<input name="ordem" type="number" min="1" value="<?php echo (int)$edicao['ordem'];?>" required></label></div><div class="th-form-row"><label class="th-field">Duração em minutos<input name="duracao_min" type="number" min="0" value="<?php echo (int)$edicao['duracao_min'];?>"></label><label class="th-field">Status<select name="status"><option value="publicado" <?php echo $edicao['status']==='publicado'?'selected':'';?>>Publicado</option><option value="rascunho" <?php echo $edicao['status']==='rascunho'?'selected':'';?>>Rascunho</option></select></label></div><label class="th-field">Objetivo<textarea name="objetivo"><?php echo esc($edicao['objetivo']);?></textarea></label><label class="th-field">Conteúdo<textarea name="conteudo" style="min-height:180px" required><?php echo esc($edicao['conteudo']);?></textarea></label><button class="th-button"><?php echo $editarId?'Salvar alterações':'Cadastrar aula';?></button></form><?php if($editarId):?><form method="post" style="margin-top:10px" onsubmit="return confirm('Remover esta aula, materiais e progresso relacionado?')"><?php echo csrfInput();?><input type="hidden" name="acao" value="excluir"><input type="hidden" name="aula_id" value="<?php echo $editarId;?>"><button class="th-button th-button-danger">Remover aula</button></form><a class="th-button th-button-secondary" style="margin-top:10px" href="aulas.php">Cancelar edição</a><?php endif;?></aside></div></main></body></html>
